/* ---- Kalkan kubbesi (kullanıcı görseli, 16 kare: oluşma 0-3 · tam 4-7 · çatlama 8-11 · kırılma 12-15).
   Kalkanın gerçek durumuna bağlıdır: verildiğinde oluşur, emdiği hasarla çatlar, bitince ya da süresi dolunca parçalanır. ---- */
var AF285_DOME_META={"cols": 4, "rows": 4, "fw": 192, "fh": 96, "ground": 0.8828828828828829, "domeTop": 0.036036036036036036, "domeW": 0.7882882882882883};
var AF285_DOME_SRC={blue:'data:image/webp;base64,',gold:'data:image/webp;base64,'};
var AF285_DOME_IMG=Object.create(null);
function af285DomeImg(c){
  const key=c===1?'gold':'blue';let im=AF285_DOME_IMG[key];
  if(!im){im=new Image();im.decoding='async';im.src=AF285_DOME_SRC[key];AF285_DOME_IMG[key]=im;}
  return im.complete&&im.naturalWidth?im:null;
}
function af285DomeOn(u,color){
  if(!u||u.hp<=0||!((u.absorb||0)>0&&(u.absorbUntil||0)>elapsed))return;
  u._af285Dome=elapsed;u._af285DomeM=Math.max(1,u.absorb);u._af285DomeC=color==='gold'?1:2;u._af285DomeB=0;
  af285DomeImg(u._af285DomeC);
}

/* ---- Zincir yıldırım (kullanıcı görseli, 16 kare: toplanma 0-3 · sıçrama 4-7 · iki uçta patlama 8-11 · sönme 12-15).
   Kareler iki birimin ayak noktası arasına gerçek mesafeye göre yatay uzatılarak çizilir. ---- */
var AF285_CHAIN_META={"cols": 4, "rows": 4, "fw": 160, "fh": 160, "ground": 0.865, "left": 0.19, "right": 0.8, "center": 0.52};
var AF285_CHAIN_SRC='data:image/webp;base64,';
var AF285_CHAIN_IMG=null;
function af285ChainImg(){
  if(!AF285_CHAIN_IMG){AF285_CHAIN_IMG=new Image();AF285_CHAIN_IMG.decoding='async';AF285_CHAIN_IMG.src=AF285_CHAIN_SRC;}
  return AF285_CHAIN_IMG.complete&&AF285_CHAIN_IMG.naturalWidth?AF285_CHAIN_IMG:null;
}

